{
  "name": "execute_function",
  "description": "Invoke a function with arguments and return its output. Optional: mocks (substitute dependency outputs), context (preseed Page/Store/Context paths), dry_run (suppress side effects), include_trace (return per-step DebugCollector log). SIDE-EFFECTING unless dry_run=true.",
  "input_schema": {
    "type": "object",
    "properties": {
      "namespace": {
        "type": "string",
        "description": "Function namespace"
      },
      "name": {
        "type": "string",
        "description": "Function local name"
      },
      "arguments": {
        "type": "object",
        "description": "{paramName: value}"
      },
      "runtime": {
        "type": "string",
        "description": "ui | core",
        "default": "core"
      },
      "app_code": {
        "type": "string",
        "description": "appCode; defaults to session"
      },
      "client_code": {
        "type": "string",
        "description": "clientCode; defaults to session"
      },
      "mocks": {
        "type": "object",
        "description": "Stub outputs by fully-qualified callable"
      },
      "context": {
        "type": "object",
        "description": "Preseed Page/Store/Context paths"
      },
      "dry_run": {
        "type": "boolean",
        "description": "Suppress side-effect steps",
        "default": false
      },
      "include_trace": {
        "type": "boolean",
        "description": "Return per-step trace",
        "default": false
      }
    },
    "required": [
      "namespace",
      "name"
    ]
  }
}
